  'tooltip.toolNode.desc': 'Click en el lienzo para colocar un punto de unión. Los nodos son donde se conectan las barras y se aplican cargas.',
  'tooltip.toolElement.title': 'Crear Elemento (E)',
  'tooltip.toolElement.desc': 'Click en un nodo de inicio, luego en uno de fin. Se crea una barra entre ambos. Frame = rígida, Truss = articulada.',
