  'tooltip.toolSupport.desc': 'Click en un nodo para colocar un apoyo. El tipo de apoyo determina qué movimientos están restringidos.',
  'tooltip.toolLoad.title': 'Aplicar Carga (L)',
  'tooltip.toolLoad.desc': 'Click en un nodo (puntual) o barra (distribuida) para aplicar una fuerza. Valores negativos = hacia abajo.',
  'tooltip.toolInfluence.title': 'Línea de Influencia (I)',
  'tooltip.toolInfluence.desc': 'Muestra cómo varía una reacción o esfuerzo cuando una carga unitaria recorre la estructura.',
