  'tooltip.toolPan.desc': 'Arrastrá para desplazar la vista. También podés usar click medio o Ctrl+arrastrar.',
  'tooltip.solve.title': 'Calcular',
  'tooltip.solve.desc': 'Resuelve la estructura por el Método de la Rigidez Directa (DSM). Necesitás nodos, barras, apoyos y cargas.',
  'tooltip.selfweight.title': 'Peso Propio',
  'tooltip.selfweight.desc': 'Agrega automáticamente cargas distribuidas por gravedad usando la densidad del material y el área de la sección.',
  'tooltip.diagNone.title': 'Sin Diagrama',
  'tooltip.diagNone.desc': 'Oculta todos los diagramas de resultados. Solo se ve la estructura.',
  'tooltip.diagDeformed.title': 'Deformada',
  'tooltip.diagDeformed.desc': 'Muestra la forma deformada amplificada. Útil para verificar que el comportamiento es razonable.',
  'tooltip.diagMoment.title': 'Momento Flector (M)',
  'tooltip.diagMoment.desc': 'Diagrama del momento que genera flexión en cada barra. Se dibuja del lado traccionado por convención.',
  'tooltip.diagShear.title': 'Corte (V)',
  'tooltip.diagShear.desc': 'Diagrama de la fuerza de corte a lo largo de cada barra. Cambios bruscos indican cargas puntuales.',
  'tooltip.diagAxial.title': 'Axil (N)',
  'tooltip.diagAxial.desc': 'Diagrama de la fuerza axial. Positivo = tracción (la barra se estira), negativo = compresión.',
  'tooltip.diagAxialColor.title': 'Color Axil (N±)',
  'tooltip.diagAxialColor.desc': 'Colorea las barras según axil: rojo = tracción, azul = compresión. Grosor proporcional a la magnitud.',
  'tooltip.diagColorMap.title': 'Mapa de Color',
  'tooltip.diagColorMap.desc': 'Colorea las barras según el esfuerzo elegido (momento, corte, axil o ratio σ/fy) usando una escala de colores.',
  'tooltip.supFixed.title': 'Empotrado',
  'tooltip.supFixed.desc': 'Restringe desplazamiento horizontal (ux), vertical (uy) y giro (θ). No permite ningún movimiento.',
  'tooltip.supPinned.title': 'Articulado',
  'tooltip.supPinned.desc': 'Restringe ux y uy, pero permite el giro. La barra puede rotar libremente en este punto.',
  'tooltip.supRollerX.title': 'Móvil en X',
  'tooltip.supRollerX.desc': 'Solo restringe uy (vertical). Permite movimiento horizontal y giro. Típico apoyo "sobre ruedas".',
  'tooltip.supRollerY.title': 'Móvil en Y',
  'tooltip.supRollerY.desc': 'Solo restringe ux (horizontal). Permite movimiento vertical y giro.',
  'tooltip.supSpring.title': 'Resorte',
  'tooltip.supSpring.desc': 'Apoyo elástico con rigidez configurable en cada dirección (kx, ky, kθ). Modela suelo o conexiones flexibles.',

