  // ─── Section Stress Panel ───
  'stress.panelTitle': 'Análisis de Sección',
  'stress.close': 'Cerrar (Esc)',
  'stress.moveAlongElem': 'Mover a lo largo del elemento (x/L)',
  'stress.forces3dHelp': 'Esfuerzos internos 3D en esta sección.\nN = normal (+ tracción, - compresión)\nVy = corte en plano XY (produce Mz)\nVz = corte en plano XZ (produce My)',
  'stress.moments3dHelp': 'Mx = momento torsor\nMy = momento sobre el eje local y (flexiona sobre el canto, usa Iy)\nMz = momento sobre el eje local z (flexiona sobre el ancho, usa Iz)\nSección vertical sin rotar: My = eje fuerte/vertical, Mz = eje débil/lateral — una rotación de la sección los gira con ella.\nConvención: + = positivo (tracción en fibra inferior)',
  'stress.rotDecompHelp': 'Descomposición por rotación de sección ({angle}°).\nVy, Vz = componentes del corte en ejes locales rotados',
  'stress.rotMomentHelp': 'Descomposición del momento M por rotación de sección.\nMy = M·cos(α) (flexión de canto/eje fuerte en α=0)\nMz = M·sin(α) (flexión de ancho/eje débil en α=0)\nα = {angle}°',
  'stress.forces2dHelp': 'Esfuerzos internos en esta sección del elemento.\nN = normal (+ tracción, - compresión)\nV = corte transversal\nM = momento flector (+ sagging, tracciona abajo)',
  'stress.criticalSections': 'Secciones criticas',
  'stress.criticalSectionsHelp': 'Posiciones a lo largo del elemento donde conviene verificar tensiones.\n\nIncluye puntos de momento maximo (V=0), apoyos, cargas puntuales y puntos intermedios.\nClick en cada chip para navegar a esa seccion.',
  'stress.amorphMsg1': 'La sección seleccionada es <strong>amorfa</strong> (sin forma geométrica definida).',
  'stress.amorphMsg2': 'Las secciones amorfas no permiten análisis de distribución de tensiones, círculo de Mohr ni criterios de falla.',
  'stress.amorphMsg3': 'Para habilitar el análisis de sección, asigne un perfil estándar o construya una sección con forma geométrica.',

  // ─── Stress State Details ───
  'stress.stressState': 'Estado tensional',
  'stress.sigmaBiaxHelp': 'Tensión normal biaxial (Navier):\nσ = N/A − My·y/Iy + Mz·z/Iz\n\nPositiva = tracción (rojo)\nNegativa = compresión (azul)\n\nDepende de la fibra (y, z) seleccionada.',
  'stress.tauTotalHelp': 'Tensión tangencial total combinada:\nτ = √(τVy² + τVz² + τT²)\n\nIncluye corte por Vy (plano XY), Vz (plano XZ) y torsión.',
  'stress.vonMisesHelp': 'Criterio de Von Mises (energía de distorsión):\nσvm = √(σ² + 3τ²)\n\nPreferido para acero y metales dúctiles.\nEl porcentaje indica uso de la capacidad fy.',
  'stress.trescaHelp': 'Criterio de Tresca (máx. tensión tangencial):\nτmax = √((σ/2)² + τ²)\n\nConservador ~15% respecto a Von Mises.\nEquivalente: 2τmax ≤ fy',
  'stress.rankineHelp': 'Criterio de Rankine (máx. tensión normal):\nmax(|σ₁|, |σ₃|) ≤ fy\n\nApropiado para materiales frágiles (hormigón, roca).\nPara acero, preferir Von Mises.',
  'stress.neutralAxis': 'Eje neutro:',
  'stress.neutralAxis3dHelp': 'Eje neutro combinado donde σ=0.\nCon flexion biaxial (Mz y My), el eje neutro puede ser oblicuo.\nθ es el angulo respecto al eje Z (horizontal).',
  'stress.sigma2dHelp': 'Tension normal (formula de Navier):\nσ = N/A + M·y/I\n\nPositiva = traccion (rojo)\nNegativa = compresion (azul)\n\nDepende de la fibra seleccionada (y).',
  'stress.tauMassiveHelp': 'Tension tangencial (Jourawski):\nτ = V·Q(y) / (I·b)\n\nQ(y) = momento estático del área por encima de y.\nMáxima en el eje neutro, nula en bordes libres.\nDistribucion parabólica en secciones rectangulares.\n\nHipótesis: τ uniforme en el ancho b.\nPara secciones anchas (b ≈ h) es una aproximación;\nel valor real varía en z (máximo en el centro).',
  'stress.tauThinHelp': 'Tension tangencial (Jourawski):\nτ = V·Q(y) / (I·b)\n\nQ(y) = momento estático del área por encima de y.\nMáxima en el eje neutro, nula en bordes libres.\n\nEn perfiles de pared delgada la hipótesis de\nτ uniforme en el espesor es muy precisa.',
  'stress.neutralAxisLabel': '(eje neutro)',
  'stress.note2dTauOnly': 'Analisis 2D: solo τxy por corte V',
  'stress.note2dNoTorsion': 'Sin torsion (T=0) ni corte fuera de plano (Vz=0)',
  'stress.neutralAxis2dHelp': 'Eje neutro (σ = 0):\ny_EN = -N·Iz / (A·M)\n\nPosición donde la tensión normal se anula.\nPositivo = por encima del baricentro.\nSi N=0, el EN pasa por el baricentro (y=0).',

  // ─── Central Core ───
  'stress.centralCore': 'Nucleo central',
  'stress.centralCoreHelp': 'El NC es una propiedad geométrica de la sección.\nDefine dónde puede actuar N sin cambio de signo en σ.\nActivar el botón NC en la sección transversal para visualizarlo.',
  'stress.ccDesc1': 'El <strong>núcleo central</strong> es una propiedad geométrica de la sección transversal, independiente de las cargas aplicadas.',
  'stress.ccDesc2': 'Define la región alrededor del baricentro donde puede actuar una fuerza normal N sin producir cambio de signo en las tensiones normales σ. Si el centro de presiones cae dentro del NC, toda la sección está en tracción o en compresión pura.',
  'stress.ccEquations': 'Ecuaciones',
  'stress.ccEqDesc': 'Para cada fibra extrema a distancia <em>d</em> del baricentro, el vértice del NC está a:',
  'stress.ccEqWhere': 'donde W = módulo resistente, A = área, I = momento de inercia, d = distancia al extremo.',
  'stress.sectionLabel': 'Sección:',
  'stress.ccShapeLabel': 'Forma del NC:',
  'stress.shapeRect': 'Rectangular',
  'stress.shapeIH': 'Doble T (I/H)',
  'stress.shapeCHS': 'Circular hueca (CHS)',
  'stress.shapeRHS': 'Rectangular hueca (RHS)',
  'stress.shapeT': 'T',
  'stress.shapeL': 'L (ángulo)',
  'stress.shapeC': 'C (canal)',
  'stress.coreCircular': 'Circular',
  'stress.coreHexagonal': 'Hexagonal',
  'stress.coreDiamond': 'Rombo (diamante)',
  'stress.ccRectNote': 'Rombo con semi-ejes e<sub>y</sub> = h/6 y e<sub>z</sub> = b/6',
  'stress.ccIHNote': 'Hexágono: vértices en (0, ±I<sub>z</sub>/(A·h/2)) y (±I<sub>y</sub>/(A·b/2), ±I<sub>z</sub>/(A·y<sub>alma</sub>))',
  'stress.ccCHSNote': 'Círculo de radio R<sub>nc</sub> = I<sub>z</sub>/(A·R) = R/4 (sección maciza)',
  'stress.ccDefaultNote': 'Rombo con e<sub>y</sub> = I<sub>z</sub>/(A·y<sub>max</sub>) y e<sub>z</sub> = I<sub>y</sub>/(A·z<sub>max</sub>)',

  // ─── Cross Section Drawing ───
  'stress.fiberY': 'Fibra y:',
  'stress.fiberZ': 'Fibra z:',
  'stress.fiberYZ3dHelp': 'Posición en los ejes Y y Z de la sección donde se evalúan las tensiones.\nY (canto): flexión por My, usa Iy. Z (ancho): flexión por Mz, usa Iz.\nEn la orientación por defecto (sin rotar) Y es el eje fuerte; una rotación de la sección lo gira.\nEl punto amarillo muestra la fibra seleccionada.',
  'stress.fiberY2dHelp': 'Altura dentro de la sección donde se evalúan las tensiones.\ny = 0 es el centro (eje neutro si N=0).\nMover el slider para recorrer desde la fibra inferior a la superior.\nEn los extremos las tensiones normales son máximas y el corte es mínimo.',

