  // ── Entrega a CAD V2 (RcCadHandoffV2) ─────────────────────────
  // V1 está congelado y declara que NO lleva las parrillas. V2 sí las lleva, y estas claves son
  // las que lo dicen. La frase de alcance vuelve a ser la más importante del bloque, por el motivo
  // inverso al de V1: acá hay que evitar que se lea como la armadura COMPLETA de la zapata.
  'footing.cadv2.assembly.description': 'Conjunto coordinado de armadura de la zapata: parrilla inferior en ambas direcciones, pelos de columna, estribos y crossties de arranque, el macizo de la zapata, un tramo de columna y la interfaz entre ambos. NO incluye armadura superior, que no fue evaluada.',
  'footing.cadv2.family.starterCrosstie': 'Crossties de arranque: ganchos de una rama que toman dos barras a través de la sección, exigidos por el artículo 10.7.6.3 cuando una barra longitudinal queda fuera del alcance de 150 mm de una barra ya restringida.',
  'footing.cadv2.family.footingBottomMatX': 'Barras de la parrilla inferior paralelas a B, repartidas a lo largo de L.',
  'footing.cadv2.family.footingBottomMatY': 'Barras de la parrilla inferior paralelas a L, repartidas a lo largo de B.',
  'footing.cadv2.scope.bottomMatModeled': 'Zapata {footing}: la parrilla inferior está modelada como geometría de barras y viaja en esta entrega — {x} barra(s) en X y {y} en Y, con su orden de capas resuelto. Un consumidor de V1 esperaba que estuvieran ausentes; en V2 están presentes.',
  'footing.cadv2.unsupported.topNotEvaluated': 'Zapata {footing}: la armadura superior NO fue evaluada. Nada en esta entrega demuestra que sea innecesaria, y su ausencia no debe leerse como que no se requiere.',
  'footing.cadv2.unsupported.punchingMoment': 'Zapata {footing}: el punzonamiento con transferencia de momento desbalanceado no está implementado. El resultado de punzonamiento que acompaña a esta entrega no cubre ese caso.',
  'footing.cadv2.unsupported.matStarterSpacing': 'Zapata {footing}: {n} par(es) parrilla/espera no cumplen la separación libre mínima del artículo 25.2.3 — el menor mide {measured} mm contra {required} mm requeridos. El conjunto NO es constructible. La geometría se exporta igual, para diagnóstico y QA visual: una falla de constructibilidad bloquea la emisión, no la visualización.',
  'geotechnical.ui.title': 'Condiciones del terreno',
  'geotechnical.ui.add': 'Agregar perfil de suelo',
  'geotechnical.ui.empty': 'Todavía no hay perfiles de suelo. Sin uno, una zapata no puede verificarse a capacidad portante.',
  'geotechnical.ui.noRegulatoryDefault': 'Ningún reglamento provee una tensión admisible: surge de un estudio de suelos. Nada se precarga acá, y un valor supuesto queda visible en todos los documentos.',
  'geotechnical.ui.name': 'Nombre',
  'geotechnical.ui.allowableBearing': 'Tensión admisible (kPa)',
